import sys

def simplify_brute(path):
    stack = []
    for p in path.split('/'):
        if p == '' or p == '.':
            continue
        if p == '..':
            if stack:
                stack.pop()
        else:
            stack.append(p)
    return '/' + '/'.join(stack)

if __name__ == '__main__':
    p = sys.stdin.readline().rstrip()
    print(simplify_brute(p))

import sys

def simplify_opt(path):
    stack = []
    i = 0
    n = len(path)
    while i < n:
        if path[i] == '/':
            i += 1
            continue
        j = i
        while j < n and path[j] != '/':
            j += 1
        seg = path[i:j]
        i = j + 1
        if seg == '' or seg == '.':
            continue
        if seg == '..':
            if stack:
                stack.pop()
        else:
            stack.append(seg)
    return '/' + '/'.join(stack)

if __name__ == '__main__':
    p = sys.stdin.readline().rstrip()
    print(simplify_opt(p))

import sys
from collections import deque

def simplify_best(path):
    stack = deque()
    for seg in path.split('/'):
        if seg in ('', '.'):
            continue
        if seg == '..':
            if stack:
                stack.pop()
        else:
            stack.append(seg)
    return '/' + '/'.join(stack)

if __name__ == '__main__':
    p = sys.stdin.readline().rstrip()
    print(simplify_best(p))
